/**
 * The sections of a menu as chips that jump to them: a nav landmark named by `label`, one link per section to
 * `#<prefix>-<key>`.
 */
import { type ReactNode } from "react";
import { Block, Link, List, ListItem } from "../compose";
import { tpl, urlOf } from "../utils";

export type MenuSectionNavProps = {
  label: string;
  sections: Array<{ id: string; key: string; title: string }>;
  prefix: string;
  landmarkLabel?: string;
};

export function MenuSectionNav({ label, sections, prefix, landmarkLabel }: MenuSectionNavProps) {
  return (
    <Block tag="nav" aria-label={(landmarkLabel ?? label)} data-slot="section-nav">
      <List tag="ul" className="flex flex-wrap gap-2">
        {(sections ?? []).map((s) => (
          <ListItem key={s.id} data-slot="sections-row">
            <Link
              href={urlOf(tpl("#{0}-{1}", prefix, s.key))}
              variant="nav"
              size="sm"
              className="h-8 rounded px-4 inset-ring inset-ring-border"
            >
              {s.title}
            </Link>
          </ListItem>
        ))}
      </List>
    </Block>
  );
}
